package com.study.room;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.boot.web.servlet.support.SpringBootServletInitializer;

@SpringBootApplication
public class StudyRoomApplication extends SpringBootServletInitializer {
    public static void main(String[] args) {
        SpringApplication.run(StudyRoomApplication.class, args);
    }

    @Override
    protected SpringApplicationBuilder configure(SpringApplicationBuilder builder) {
        return builder.sources(StudyRoomApplication.class);
    }
}

package com.study.room.exception;

public class ReservationNotFoundException extends RuntimeException {
    public ReservationNotFoundException(int reservationId) {
        super("예약 " + reservationId + "번을 찾을 수 없습니다");
    }
}

package com.study.room.exception;

public class RoomFullException extends RuntimeException {
    public RoomFullException(String roomName, int remaining) {
        super(roomName + "의 남은 자리는 " + remaining + "명입니다");
    }
}

package com.study.room.mapper;

import java.util.List;

import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;

import com.study.room.model.Reservation;
import com.study.room.model.StudyRoom;

@Mapper
public interface ReservationMapper {
    List<StudyRoom> findRooms();

    StudyRoom findRoom(int roomId);

    int sumPeople(int roomId);

    List<Reservation> search(@Param("roomId") Integer roomId, @Param("keyword") String keyword);

    Reservation findById(int reservationId);

    int insert(Reservation reservation);

    int delete(int reservationId);
}

package com.study.room.model;

public class Reservation {
    private Integer reservationId;
    private Integer roomId;
    private String roomName;
    private String memberName;
    private int people;

    public Integer getReservationId() {
        return reservationId;
    }

    public void setReservationId(Integer reservationId) {
        this.reservationId = reservationId;
    }

    public Integer getRoomId() {
        return roomId;
    }

    public void setRoomId(Integer roomId) {
        this.roomId = roomId;
    }

    public String getRoomName() {
        return roomName;
    }

    public void setRoomName(String roomName) {
        this.roomName = roomName;
    }

    public String getMemberName() {
        return memberName;
    }

    public void setMemberName(String memberName) {
        this.memberName = memberName;
    }

    public int getPeople() {
        return people;
    }

    public void setPeople(int people) {
        this.people = people;
    }
}

package com.study.room.model;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

public class ReservationForm {
    @NotNull(message = "방을 선택하세요")
    private Integer roomId;

    @NotBlank(message = "예약자 이름을 입력하세요")
    @Size(max = 30, message = "예약자 이름은 30자 이하입니다")
    private String memberName;

    @NotNull(message = "인원을 입력하세요")
    @Min(value = 1, message = "인원은 1명 이상입니다")
    private Integer people;

    public Integer getRoomId() {
        return roomId;
    }

    public void setRoomId(Integer roomId) {
        this.roomId = roomId;
    }

    public String getMemberName() {
        return memberName;
    }

    public void setMemberName(String memberName) {
        this.memberName = memberName;
    }

    public Integer getPeople() {
        return people;
    }

    public void setPeople(Integer people) {
        this.people = people;
    }
}

